        printf '\003\000\000\000\004\000\000\000\020\000\000\000\035\000\000\000\003\000\000\000\002\000\000\000\044\005\000\000\044\005\000\000\367\001\000\000\000\000\000\000\000\000\000\000\001\000\000\000\000\000\000\000\045\000\000\000\377\377\377\157\002\000\000\000'
