        printf '\000\000\000\000\350\060\000\000\022\000\000\000\000\000\000\000\000\000\000\000\001\000\000\000\001\000\000\000\261\000\000\000\003\000\000\160\000\000\000\000\000\000\000\000\372\060\000\000\061\000\000\000\000\000\000\000\000\000\000\000\001\000\000\000'
